-- New questions for literatura: 120 questions, each already
-- with its en/es translation (240 translation rows).
--
-- ids are deterministic (uuid5 of the pt-BR prompt), so running this twice
-- inserts nothing new: questions use on conflict do nothing, translations
-- on conflict do update. The translation join refuses any row whose option
-- count differs from the original (correct_index is positional).

insert into questions (id, catalog_node_id, prompt, options, correct_index, explanation, order_index, difficulty)
select v.id::uuid, v.node::uuid, v.prompt, v.options, v.correct_index, v.explanation, v.order_index, v.difficulty
from (values
  ('bcef25c3-1638-50ea-914e-32e5bc26404a', '47653aa7-d471-5270-9cfe-c1567fab81d2',
   'O gênero lírico caracteriza-se principalmente por:',
   array['Narrar uma história com personagens e enredo', 'Expressar emoções e a subjetividade de um eu lírico', 'Ser escrito para encenação no palco', 'Apresentar argumentos científicos'], 1,
   'No lírico, predomina a expressão de sentimentos e impressões do eu lírico, geralmente em poemas.', 100, 'facil'),
  ('c51700f1-357e-5f3e-8cd7-bbdc91ea27f4', '47653aa7-d471-5270-9cfe-c1567fab81d2',
   'Romance, conto e crônica pertencem ao gênero:',
   array['Lírico', 'Dramático', 'Didático', 'Narrativo (épico)'], 3,
   'São textos que contam uma história, com narrador, personagens, tempo e espaço.', 101, 'facil'),
  ('33bdecee-4de1-5924-b2cf-ecbef5835759', '47653aa7-d471-5270-9cfe-c1567fab81d2',
   'No gênero dramático, a história é apresentada principalmente por meio:',
   array['Dos diálogos e ações das personagens, sem narrador', 'Da voz de um narrador onisciente', 'De versos que expressam só sentimentos', 'De notas de rodapé'], 0,
   'O texto teatral se realiza na encenação; as rubricas orientam cenário e movimentos.', 102, 'medio'),
  ('b03e35ec-a966-51fb-9cae-e70a2f9edb82', '47653aa7-d471-5270-9cfe-c1567fab81d2',
   'A crônica, gênero muito praticado no Brasil por autores como Rubem Braga, caracteriza-se por:',
   array['Ser um longo poema épico', 'Narrar feitos heroicos de um povo', 'Partir de fatos do cotidiano, com linguagem leve e publicação em jornais e revistas', 'Ser escrita apenas em versos rimados'], 2,
   'A crônica comenta o dia a dia de forma pessoal, muitas vezes com humor ou lirismo.', 103, 'medio'),
  ('5456d7a4-5f92-53ed-b102-fb34c8585ea4', '47653aa7-d471-5270-9cfe-c1567fab81d2',
   'O narrador que conhece os pensamentos e sentimentos de todas as personagens é chamado de:',
   array['Narrador-personagem', 'Narrador onisciente', 'Narrador observador limitado', 'Eu lírico'], 1,
   'O narrador onisciente, em terceira pessoa, sabe tudo sobre a história e as personagens.', 104, 'dificil'),
  ('1c3216c8-9f11-5e57-b495-f4087681da69', '47653aa7-d471-5270-9cfe-c1567fab81d2',
   'A epopeia, como Os Lusíadas, é um poema narrativo longo que:',
   array['Expressa apenas as emoções íntimas do poeta', 'É escrito para ser encenado', 'Critica os costumes com humor', 'Narra feitos grandiosos de um herói ou de um povo'], 3,
   'A epopeia celebra ações heroicas coletivas; Os Lusíadas narra as navegações portuguesas.', 105, 'dificil'),
  ('6a2b8226-6ecc-5b16-9f67-93730502a617', '568bb871-cde8-5186-83b7-c0d7f350c8a0',
