  ('743bf090-f14f-5438-997b-254ad2c6875a', 'ee4e7364-bda5-5dbd-a32e-5407faf9aa86',
   'José de Alencar escreveu romances indianistas, como:',
   array['Dom Casmurro', 'O Cortiço', 'Iracema', 'Macunaíma'], 2,
