   array['É um jovem idealista que distribui suas terras', 'É um indígena que narra sua aldeia', 'Conta sua trajetória de ambição e posse, que destrói suas relações e seu casamento com Madalena', 'Narra uma aventura cômica em versos'], 2,
   'O fazendeiro que reduz tudo à propriedade acaba solitário; o romance critica a lógica do capital.', 182, 'dificil'),
  ('ab33bd13-e31c-5227-b302-f76d7a5f260f', '2fce8c11-3365-5689-9765-947155818c58',
